/**
 * Roslyn worker: per-project compilations and SDK implicit global usings
 * (PROTOCOL.md v1 `projects` request field).
 *
 * Background: SDK-style projects with `<ImplicitUsings>enable</ImplicitUsings>`
 * get `global using` directives generated by the .NET SDK at build time. A worker
 * that compiles the sources without them reports false CS0246/CS0103 diagnostics
 * and degrades CALLS to BCL members. Compiling every project's sources into ONE
 * compilation also produces artifacts such as CS7022 (top-level statements of
 * one project make another project's `Main` look ignored).
 *
 * These tests drive the worker binary directly over stdin/stdout. Every positive
 * case has a control case that proves diagnostics are not filtered: the same
 * sources without the project model keep their compiler diagnostics.
 *
 * Process safety: the worker is started with the literal `dotnet` executable, a
 * fixed argument array and shell: false; inputs travel only over stdin.
 */
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { beforeAll, describe, expect, it } from "vitest";
import { buildRoslynWorkerBinary } from "./roslyn-worker-build.js";

const REPO_ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const WORKER_DLL = join(
  REPO_ROOT,
  "native",
  "roslyn-worker",
  "bin",
  "Debug",
  "net10.0",
  "Causoryn.RoslynWorker.dll",
);

interface NodeRef {
  kind: string;
  qualifiedName: string;
  relativePath?: string | null;
}

interface WorkerEdge {
  kind: string;
  from: NodeRef;
  to: NodeRef;
  resolution: string;
  evidence: Array<{ rationale: string }>;
}

interface WorkerResponse {
  id: unknown;
  status: string;
  diagnostics?: Array<{ relativePath: string; code: string; message: string; line: number }>;
  edges?: WorkerEdge[];
  warnings?: string[];
  error?: { code: string; message: string };
}

const dotnetCheck = spawnSync("dotnet", ["--version"], { encoding: "utf8", shell: false });
const dotnetAvailable = dotnetCheck.status === 0;
if (!dotnetAvailable) {
  console.error(
    "[roslyn-worker-projects] dotnet SDK not found: project-model worker tests were not run (reported as not executed)",
  );
} else {
  const build = buildRoslynWorkerBinary();
  if (build.status !== 0 || !existsSync(WORKER_DLL)) {
    throw new Error(
      `worker build failed (exit=${String(build.status)}); tests are not run against a stale binary` +
        (build.stdout ? ` [stdout]: ${build.stdout.slice(-400)}` : ""),
    );
  }
}

function runWorker(requests: unknown[]): WorkerResponse[] {
  const input = requests.map((request) => JSON.stringify(request)).join("\n") + "\n";
  const result = spawnSync("dotnet", ["exec", WORKER_DLL], {
    input,
    encoding: "utf8",
    maxBuffer: 64 * 1024 * 1024,
    shell: false,
  });
  const stdout = typeof result.stdout === "string" ? result.stdout : "";
  return stdout
    .split("\n")
    .filter((line) => line.trim().length > 0)
    .map((line) => JSON.parse(line) as WorkerResponse);
}

function analyze(id: string, files: Array<{ path: string; content: string }>, projects?: unknown[]): unknown {
  return {
    id,
    type: "analyze",
    protocolVersion: "1",
    files,
    ...(projects === undefined ? {} : { projects }),
  };
}

function codes(response: WorkerResponse | undefined, relativePath?: string): string[] {
  return (response?.diagnostics ?? [])
    .filter((diag) => relativePath === undefined || diag.relativePath === relativePath)
    .map((diag) => diag.code)
    .sort();
}

function callEdge(
  response: WorkerResponse | undefined,
  fromQualifiedName: string,
  toQualifiedName: string,
): WorkerEdge | undefined {
  return (response?.edges ?? []).find(
    (edge) =>
      edge.kind === "CALLS" &&
      edge.from.qualifiedName === fromQualifiedName &&
      edge.to.qualifiedName === toQualifiedName,
  );
}

/** SDK defaults for Microsoft.NET.Sdk (Microsoft Learn "Implicit using directives"). */
const SDK_DEFAULT_USINGS = [
  "System",
  "System.Collections.Generic",
  "System.IO",
  "System.Linq",
  "System.Net.Http",
  "System.Threading",
  "System.Threading.Tasks",
].map((name) => ({ name }));

/** Uses Console, Thread and List<T> with no explicit using directive. */
const RUNNER_SOURCE = [
  "namespace App;",
  "",
  "public static class Runner",
  "{",
  "    public static int Run()",
  "    {",
  "        Console.WriteLine(\"start\");",
  "        Thread.Sleep(1);",
  "        var items = new List<int>();",
  "        items.Add(1);",
  "        return items.Count;",
  "    }",
  "}",
  "",
].join("\n");

const LIB_CONSOLE_SOURCE = [
  "namespace Lib;",
  "",
  "public static class Logger",
  "{",
  "    public static void Log() => Console.WriteLine(\"lib\");",
  "}",
  "",
].join("\n");

const TOP_LEVEL_TOOL = "System.Console.WriteLine(\"tool\");\n";

const MAIN_PROGRAM = [
  "namespace Svc;",
  "",
  "public static class Program",
  "{",
  "    public static int Main() => 0;",
  "}",
  "",
].join("\n");

describe.skipIf(!dotnetAvailable)("roslyn-worker projects: SDK implicit global usings", () => {
  const responses = new Map<string, WorkerResponse>();

  beforeAll(() => {
    const runnerFile = { path: "App/Runner.cs", content: RUNNER_SOURCE };
    const requests = [
      analyze("usings-on", [runnerFile], [{ path: "App/App.csproj", globalUsings: SDK_DEFAULT_USINGS }]),
      analyze("usings-on-repeat", [runnerFile], [{ path: "App/App.csproj", globalUsings: SDK_DEFAULT_USINGS }]),
      analyze("usings-control-no-projects", [runnerFile]),
      analyze("usings-control-empty-list", [runnerFile], [{ path: "App/App.csproj", globalUsings: [] }]),
      analyze(
        "usings-no-leak",
        [runnerFile, { path: "Lib/Logger.cs", content: LIB_CONSOLE_SOURCE }],
        [
          { path: "App/App.csproj", globalUsings: SDK_DEFAULT_USINGS },
          { path: "Lib/Lib.csproj" },
        ],
      ),
      analyze(
        "usings-unresolvable",
        [runnerFile],
        [{ path: "App/App.csproj", globalUsings: [...SDK_DEFAULT_USINGS, { name: "Does.Not.Exist" }] }],
      ),
      analyze(
        "usings-static-alias",
        [
          {
            path: "Calc/Calc.cs",
            content: [
              "namespace Calc;",
              "public static class Geometry",
              "{",
              "    public static string Describe()",
              "    {",
              "        var builder = new SB();",
              "        builder.Append(Sqrt(16.0));",
              "        return builder.ToString();",
              "    }",
              "}",
              "",
            ].join("\n"),
          },
        ],
        [
          {
            path: "Calc/Calc.csproj",
            globalUsings: [
              { name: "System" },
              { name: "System.Math", static: true },
              { name: "System.Text.StringBuilder", alias: "SB" },
            ],
          },
        ],
      ),
    ];
    const lines = runWorker(requests);
    for (const response of lines) {
      responses.set(String(response.id), response);
    }
  }, 180_000);

  it("project globalUsings remove false CS0246/CS0103 for Console, Thread and List<T>", () => {
    const response = responses.get("usings-on");
    expect(response?.status).toBe("ready");
    expect(codes(response)).toEqual([]);
  });

  it("BCL calls become verified CALLS edges to explicit external nodes", () => {
    const response = responses.get("usings-on");
    expect(callEdge(response, "App.Runner.Run", "System.Console.WriteLine")?.resolution).toBe("verified");
    expect(callEdge(response, "App.Runner.Run", "System.Threading.Thread.Sleep")?.resolution).toBe("verified");
    expect(callEdge(response, "App.Runner.Run", "System.Collections.Generic.List")?.resolution).toBe("verified");
    expect(
      (response?.edges ?? []).filter((edge) => edge.resolution === "unresolved"),
    ).toEqual([]);
  });

  it("control: the same sources without a project model keep their compiler diagnostics", () => {
    const response = responses.get("usings-control-no-projects");
    expect(response?.status).toBe("partial");
    expect(codes(response)).toContain("CS0103");
    expect(codes(response)).toContain("CS0246");
    expect(callEdge(response, "App.Runner.Run", "Console.WriteLine")?.resolution).toBe("unresolved");
  });

  it("control: a project with an empty globalUsings list keeps its compiler diagnostics", () => {
    const response = responses.get("usings-control-empty-list");
    expect(response?.status).toBe("partial");
    expect(codes(response)).toContain("CS0103");
    expect(codes(response)).toContain("CS0246");
  });

  it("global usings apply per project and never leak into another project's compilation", () => {
    const response = responses.get("usings-no-leak");
    expect(codes(response, "App/Runner.cs")).toEqual([]);
    expect(codes(response, "Lib/Logger.cs")).toContain("CS0103");
  });

  it("an unresolvable generated global using is reported as an explicit warning, not dropped", () => {
    const response = responses.get("usings-unresolvable");
    expect(codes(response)).toEqual([]);
    expect(
      (response?.warnings ?? []).some(
        (warning) =>
          // `global::Does.Not.Exist` → CS0400 (not found in the global namespace).
          warning.startsWith("generated global using of project 'App/App.csproj' reported CS0400") &&
          warning.includes("Does"),
      ),
    ).toBe(true);
  });

  it("static and alias global usings resolve members and types", () => {
    const response = responses.get("usings-static-alias");
    expect(codes(response)).toEqual([]);
    expect(callEdge(response, "Calc.Geometry.Describe", "System.Text.StringBuilder")?.resolution).toBe(
      "verified",
    );
    expect(callEdge(response, "Calc.Geometry.Describe", "System.Math.Sqrt")?.resolution).toBe("verified");
  });

  it("determinism: the same request yields byte-identical output", () => {
    const first = responses.get("usings-on");
    const repeat = responses.get("usings-on-repeat");
    expect(JSON.stringify({ ...repeat, id: "x" })).toBe(JSON.stringify({ ...first, id: "x" }));
  });
});

describe.skipIf(!dotnetAvailable)("roslyn-worker projects: one compilation per project", () => {
  const responses = new Map<string, WorkerResponse>();

  beforeAll(() => {
    const toolFile = { path: "Tool/Program.cs", content: TOP_LEVEL_TOOL };
    const svcFile = { path: "Svc/Program.cs", content: MAIN_PROGRAM };
    const greeter = {
      path: "Lib/Greeter.cs",
      content: [
        "namespace Lib;",
        "public static class Greeter",
        "{",
        "    public static Core.Message Hello() => new Core.Message();",
        "}",
        "",
      ].join("\n"),
    };
    const core = {
      path: "Core/Message.cs",
      content: ["namespace Core;", "public sealed class Message { }", ""].join("\n"),
    };
    const app = {
      path: "App/Caller.cs",
      content: [
        "namespace App;",
        "public static class Caller",
        "{",
        "    public static Core.Message Call() => Lib.Greeter.Hello();",
        "}",
        "",
      ].join("\n"),
    };
    const requests = [
      analyze("split-entry-points", [toolFile, svcFile], [{ path: "Tool/Tool.csproj" }, { path: "Svc/Svc.csproj" }]),
      analyze("merged-entry-points", [toolFile, svcFile]),
      analyze(
        "same-project-entry-points",
        [
          { path: "Svc/Program.cs", content: MAIN_PROGRAM },
          { path: "Svc/Script.cs", content: TOP_LEVEL_TOOL },
        ],
        [{ path: "Svc/Svc.csproj" }],
      ),
      analyze(
        "project-references",
        [app, greeter, core],
        [
          { path: "App/App.csproj", projectReferences: ["Lib/Lib.csproj"] },
          { path: "Lib/Lib.csproj", projectReferences: ["Core/Core.csproj"] },
          { path: "Core/Core.csproj" },
        ],
      ),
      analyze(
        "missing-project-reference",
        [app, greeter, core],
        [
          { path: "App/App.csproj" },
          { path: "Lib/Lib.csproj", projectReferences: ["Core/Core.csproj"] },
          { path: "Core/Core.csproj" },
        ],
      ),
      analyze(
        "project-reference-cycle",
        [app, greeter, core],
        [
          { path: "App/App.csproj", projectReferences: ["Lib/Lib.csproj"] },
          { path: "Lib/Lib.csproj", projectReferences: ["Core/Core.csproj", "App/App.csproj"] },
          { path: "Core/Core.csproj", projectReferences: ["Lib/Lib.csproj"] },
        ],
      ),
    ];
    for (const response of runWorker(requests)) {
      responses.set(String(response.id), response);
    }
  }, 180_000);

  it("CS7022 is not reported when top-level statements and Main live in different projects", () => {
    expect(codes(responses.get("split-entry-points"))).toEqual([]);
    expect(responses.get("split-entry-points")?.status).toBe("ready");
  });

  it("control: merging both projects into one compilation is what produced CS7022", () => {
    expect(codes(responses.get("merged-entry-points"))).toContain("CS7022");
  });

  it("control: CS7022 inside a single project is genuine and still reported", () => {
    expect(codes(responses.get("same-project-entry-points"))).toContain("CS7022");
  });

  it("ProjectReference (transitive) resolves cross-project calls to the referenced project's symbols", () => {
    const response = responses.get("project-references");
    expect(codes(response)).toEqual([]);
    const edge = callEdge(response, "App.Caller.Call", "Lib.Greeter.Hello");
    expect(edge?.resolution).toBe("verified");
    expect(edge?.to.kind).toBe("Method");
    expect(edge?.to.relativePath).toBe("Lib/Greeter.cs");
  });

  it("control: without the ProjectReference the referencing project cannot see the other project", () => {
    const response = responses.get("missing-project-reference");
    expect(codes(response, "App/Caller.cs")).toContain("CS0246");
    expect(codes(response, "Lib/Greeter.cs")).toEqual([]);
  });

  it("a ProjectReference cycle is broken deterministically with an explicit warning", () => {
    const response = responses.get("project-reference-cycle");
    expect(response?.status).not.toBe("error");
    expect(
      (response?.warnings ?? []).some((warning) => warning.includes("ProjectReference cycle")),
    ).toBe(true);
  });
});

describe.skipIf(!dotnetAvailable)("roslyn-worker projects: request validation", () => {
  const responses = new Map<string, WorkerResponse>();
  const file = { path: "App/Runner.cs", content: RUNNER_SOURCE };

  beforeAll(() => {
    const requests = [
      analyze("bad-unknown-project-field", [file], [{ path: "App/App.csproj", extra: 1 }]),
      analyze("bad-using-injection", [file], [
        { path: "App/App.csproj", globalUsings: [...SDK_DEFAULT_USINGS, { name: "System; class Injected { }" }] },
      ]),
      analyze("bad-using-unknown-field", [file], [
        { path: "App/App.csproj", globalUsings: [{ name: "System", global: true }] },
      ]),
      analyze("bad-static-alias", [file], [
        { path: "App/App.csproj", globalUsings: [...SDK_DEFAULT_USINGS, { name: "System.Math", static: true, alias: "M" }] },
      ]),
      analyze("bad-alias", [file], [
        { path: "App/App.csproj", globalUsings: [...SDK_DEFAULT_USINGS, { name: "System.Math", alias: "A.B" }] },
      ]),
      // U+1D49C is a letter, but a surrogate pair in UTF-16: no C# identifier character.
      analyze("bad-using-supplementary-name", [file], [
        { path: "App/App.csproj", globalUsings: [...SDK_DEFAULT_USINGS, { name: "System.\u{1D49C}Lib" }] },
      ]),
      analyze("bad-using-supplementary-alias", [file], [
        { path: "App/App.csproj", globalUsings: [...SDK_DEFAULT_USINGS, { name: "System.Text", alias: "\u{1D49C}" }] },
      ]),
      analyze("bad-project-escape", [file], [{ path: "../App.csproj" }]),
      analyze("bad-project-absolute", [file], [{ path: "C:/App/App.csproj" }]),
      analyze("bad-project-extension", [file], [{ path: "App/App.vbproj" }]),
      analyze("bad-project-same-dir", [file], [{ path: "App/A.csproj" }, { path: "App/B.csproj" }]),
      analyze("bad-project-reference", [file], [
        { path: "App/App.csproj", projectReferences: ["../Lib/Lib.csproj"] },
      ]),
      analyze("bad-assembly-name", [file], [{ path: "App/App.csproj", assemblyName: "bad/name" }]),
      analyze("bad-assembly-name-newline", [file], [{ path: "App/App.csproj", assemblyName: "App\n" }]),
      analyze("bad-usings-many", [file], [
        {
          path: "App/App.csproj",
          globalUsings: [...SDK_DEFAULT_USINGS, { name: "Bad Name" }, { name: "A.B", alias: "X.Y" }, { name: "System.Math", static: true, alias: "M" }],
        },
      ]),
      analyze("bad-using-newline", [file], [
        { path: "App/App.csproj", globalUsings: [...SDK_DEFAULT_USINGS, { name: "System\n" }] },
      ]),
    ];
    for (const response of runWorker(requests)) {
      responses.set(String(response.id), response);
    }
  }, 180_000);

  it.each([
    "bad-unknown-project-field",
    "bad-using-unknown-field",
    "bad-project-escape",
    "bad-project-absolute",
    "bad-project-extension",
    "bad-project-same-dir",
    "bad-project-reference",
    "bad-assembly-name",
    "bad-assembly-name-newline",
  ])("%s is rejected with INVALID_ARGUMENT and an English message", (id) => {
    const response = responses.get(id);
    expect(response?.status).toBe("error");
    expect(response?.error?.code).toBe("INVALID_ARGUMENT");
    expect(response?.error?.message ?? "").not.toMatch(/[çğıöşüÇĞİÖŞÜ]/);
  });

  // A global using the worker cannot accept (not a dotted C# name, an alias that is
  // not one identifier, static together with alias) is dropped with a warning; the
  // request is analyzed and its other usings apply (security finding F22: one bad
  // entry must not drop every C# file of the workspace to file-level facts). The
  // dropped text never reaches the generated global usings tree.
  it.each([
    ["bad-using-injection", "is not a dotted C# name"],
    ["bad-static-alias", "is both static and aliased"],
    ["bad-alias", "has an alias that is not a C# identifier"],
    ["bad-using-newline", "is not a dotted C# name"],
    ["bad-using-supplementary-name", "is not a dotted C# name"],
    ["bad-using-supplementary-alias", "has an alias that is not a C# identifier"],
  ])("%s: the invalid global using is dropped with a warning and the request is analyzed", (id, reason) => {
    const response = responses.get(id);
    expect(response?.status).not.toBe("error");
    expect(response?.error).toBeUndefined();
    const skipped = (response?.warnings ?? []).filter((warning) => warning.includes("global using") && warning.includes("skipped"));
    expect(skipped).toHaveLength(1);
    expect(skipped[0]).toContain("App/App.csproj");
    expect(skipped[0]).toContain(reason);
    expect(skipped[0]).not.toMatch(/[\u0000-\u001f]/);
    expect(skipped[0]).not.toMatch(/[çğıöşüÇĞİÖŞÜ]/);
    // The valid using of the same project still applies (Console resolves).
    expect(callEdge(response, "App.Runner.Run", "System.Console.WriteLine")?.resolution).toBe("verified");
    expect(JSON.stringify(response?.edges ?? [])).not.toContain("Injected");
    // Nor does it become a declaration: no node carries the injected class.
    expect(JSON.stringify(response?.nodes ?? [])).not.toContain("Injected");
  });

  it("several invalid global usings of one project give one detailed warning plus a count (bounded warnings)", () => {
    const response = responses.get("bad-usings-many");
    expect(response?.status).not.toBe("error");
    const warnings = (response?.warnings ?? []).filter((warning) => warning.includes("App/App.csproj") && warning.includes("skipped"));
    expect(warnings).toEqual([
      "global using 'Bad Name' of project 'App/App.csproj' was skipped: it is not a dotted C# name",
      "2 further global usings of project 'App/App.csproj' were skipped for the same kinds of reasons",
    ]);
    expect(callEdge(response, "App.Runner.Run", "System.Console.WriteLine")?.resolution).toBe("verified");
  });
});
